//! Chains generated by `testdata/generate.sh` (OpenSSL) and the embedded
//! real roots. CA certificates are valid 2025..2035, leaves 2026..2027.

use super::*;

macro_rules! cert {
    ($name:literal) => {
        include_bytes!(concat!("../testdata/", $name, ".der")) as &[u8]
    };
}

const RSA_ROOT: &[u8] = cert!("rsa-root");
const RSA_INT: &[u8] = cert!("rsa-int");
const RSA_LEAF: &[u8] = cert!("rsa-leaf");
const RSA_PSS_LEAF: &[u8] = cert!("rsa-pss-leaf");
const EC_ROOT: &[u8] = cert!("ec-root");
const EC_INT: &[u8] = cert!("ec-int");
const EC_LEAF: &[u8] = cert!("ec-leaf");
const ED_ROOT: &[u8] = cert!("ed-root");
const ED_LEAF: &[u8] = cert!("ed-leaf");
const NOTCA_LEAF: &[u8] = cert!("notca-leaf");
const PLEN_INT0: &[u8] = cert!("plen-int0");
const PLEN_INT1: &[u8] = cert!("plen-int1");
const PLEN_LEAF: &[u8] = cert!("plen-leaf");
const CRIT_LEAF: &[u8] = cert!("crit-leaf");
const LONG: [&[u8]; 8] = [
    cert!("long-leaf"),
    cert!("long-int7"),
    cert!("long-int6"),
    cert!("long-int5"),
    cert!("long-int4"),
    cert!("long-int3"),
    cert!("long-int2"),
    cert!("long-int1"),
];

/// 2026-06-01T00:00:00Z
const NOW: u64 = 1_780_272_000;
const JAN_2026: u64 = 1_767_225_600;
const JAN_2027: u64 = 1_798_761_600;

#[test]
fn parses_rsa_chain() {
    let root = Certificate::parse(RSA_ROOT).unwrap();
    assert_eq!(root.signature_algorithm, SignatureAlgorithm::RsaPkcs1Sha256);
    assert!(root.is_ca && root.issuer == root.subject);
    assert_eq!(root.not_after, 2_682_374_400); // GeneralizedTime 2055-01-01
    assert_eq!(root.common_name, Some("AriCode Test RSA Root"));
    let int = Certificate::parse(RSA_INT).unwrap();
    assert_eq!(int.signature_algorithm, SignatureAlgorithm::RsaPkcs1Sha384);
    assert_eq!(int.issuer, root.subject);
    assert!(int.is_ca && int.max_path_len.is_none());
    let leaf = Certificate::parse(RSA_LEAF).unwrap();
    assert_eq!(leaf.signature_algorithm, SignatureAlgorithm::RsaPkcs1Sha512);
    assert_eq!((leaf.not_before, leaf.not_after), (JAN_2026, JAN_2027));
    assert_eq!(leaf.dns_names, ["*.example.com", "example.com"]);
    assert_eq!(leaf.common_name, Some("example.com"));
    assert!(!leaf.is_ca);
    match leaf.public_key {
        PublicKey::Rsa { n, e } => assert_eq!((n.len(), e), (256, &[1, 0, 1][..])),
        other => panic!("{other:?}"),
    }
    let pss = Certificate::parse(RSA_PSS_LEAF).unwrap();
    assert_eq!(
        pss.signature_algorithm,
        SignatureAlgorithm::RsaPss(Hash::Sha256)
    );
}

#[test]
fn parses_ec_and_ed25519() {
    let root = Certificate::parse(EC_ROOT).unwrap();
    assert_eq!(root.signature_algorithm, SignatureAlgorithm::EcdsaSha384);
    assert!(
        matches!(root.public_key, PublicKey::Ec { curve: Curve::P384, point } if point.len() == 97)
    );
    let leaf = Certificate::parse(EC_LEAF).unwrap();
    assert_eq!(leaf.signature_algorithm, SignatureAlgorithm::EcdsaSha256);
    assert!(
        matches!(leaf.public_key, PublicKey::Ec { curve: Curve::P256, point } if point.len() == 65)
    );
    let ed = Certificate::parse(ED_LEAF).unwrap();
    assert_eq!(ed.signature_algorithm, SignatureAlgorithm::Ed25519);
    assert!(matches!(ed.public_key, PublicKey::Ed25519(_)));
    assert!(ed.dns_names.is_empty() && !ed.is_ca);
    assert_eq!(ed.common_name, Some("ed.example.net"));
}

#[test]
fn rejects_malformed_and_unsupported() {
    // Every truncation of a valid certificate is rejected, never panics.
    for len in 0..RSA_LEAF.len() {
        assert_eq!(
            Certificate::parse(&RSA_LEAF[..len]).err(),
            Some(Error::Malformed),
            "{len}"
        );
    }
    let mut trailing = RSA_LEAF.to_vec();
    trailing.push(0);
    assert_eq!(Certificate::parse(&trailing).err(), Some(Error::Malformed));
    // Unknown critical extension.
    assert_eq!(
        Certificate::parse(CRIT_LEAF).err(),
        Some(Error::Unsupported)
    );
    // SHA-1 signature (a real root): unsupported as a certificate, usable as an anchor.
    let digicert = roots::DEFAULT
        .iter()
        .find(|r| contains(r, b"DigiCert Global Root CA"))
        .unwrap();
    assert_eq!(Certificate::parse(digicert).err(), Some(Error::Unsupported));
    assert!(Parsed::parse(digicert).is_ok());
}

fn contains(haystack: &[u8], needle: &[u8]) -> bool {
    haystack.windows(needle.len()).any(|w| w == needle)
}

#[test]
fn hostname_matching() {
    let leaf = Certificate::parse(RSA_LEAF).unwrap();
    for host in [
        "example.com",
        "EXAMPLE.com",
        "www.example.com",
        "a-b.Example.COM",
        "www.example.com.",
    ] {
        assert!(matches_hostname(&leaf, host), "{host}");
    }
    for host in [
        "",
        ".",
        "a.b.example.com",
        "example.org",
        "wwwexample.com",
        ".example.com",
        "*.example.com",
        "com",
    ] {
        assert!(!matches_hostname(&leaf, host), "{host}");
    }
    // Common name only when there is no subjectAltName dNSName.
    let ed = Certificate::parse(ED_LEAF).unwrap();
    assert!(matches_hostname(&ed, "ed.example.net") && !matches_hostname(&ed, "x.example.net"));
    let ec = Certificate::parse(EC_LEAF).unwrap();
    assert!(matches_hostname(&ec, "www.example.org") && !matches_hostname(&ec, "example.org"));

    assert!(!name_matches("*.com", "example.com"));
    assert!(!name_matches("w*.example.com", "www.example.com"));
    assert!(!name_matches("*.*.example.com", "a.b.example.com"));
    assert!(!name_matches("www.*.com", "www.example.com"));
    assert!(name_matches("example.com.", "example.com"));
}

#[test]
fn verifies_good_chains() {
    let leaf = verify_chain(
        &[RSA_LEAF, RSA_INT],
        &[RSA_ROOT],
        "www.example.com",
        Some(NOW),
    )
    .unwrap();
    assert_eq!(leaf.common_name, Some("example.com"));
    verify_chain(
        &[RSA_PSS_LEAF, RSA_INT],
        &[RSA_ROOT],
        "pss.example.com",
        Some(NOW),
    )
    .unwrap();
    verify_chain(&[EC_LEAF, EC_INT], &[EC_ROOT], "www.example.org", Some(NOW)).unwrap();
    verify_chain(&[ED_LEAF], &[ED_ROOT], "ed.example.net", Some(NOW)).unwrap();
    // Server sends the root too, intermediates out of order, extra certificates.
    verify_chain(
        &[RSA_LEAF, RSA_ROOT, RSA_INT],
        &[RSA_ROOT],
        "example.com",
        Some(NOW),
    )
    .unwrap();
    verify_chain(
        &[EC_LEAF, ED_LEAF, EC_INT, CRIT_LEAF],
        &[ED_ROOT, RSA_ROOT, EC_ROOT],
        "www.example.org",
        None,
    )
    .unwrap();
    // Intermediate configured as the trust anchor; leaf pinned directly.
    verify_chain(&[RSA_LEAF], &[RSA_INT], "example.com", Some(NOW)).unwrap();
    verify_chain(&[ED_LEAF], &[ED_LEAF], "ed.example.net", Some(NOW)).unwrap();
    // Validity bounds are inclusive.
    verify_chain(
        &[EC_LEAF, EC_INT],
        &[EC_ROOT],
        "www.example.org",
        Some(JAN_2026),
    )
    .unwrap();
    verify_chain(
        &[EC_LEAF, EC_INT],
        &[EC_ROOT],
        "www.example.org",
        Some(JAN_2027),
    )
    .unwrap();
}

#[test]
fn chain_errors() {
    let host = "www.example.com";
    let rsa = |chain: &[&[u8]], roots: &[&[u8]], now| verify_chain(chain, roots, host, now).err();
    assert_eq!(
        rsa(&[RSA_LEAF, RSA_INT], &[RSA_ROOT], Some(JAN_2027 + 1)),
        Some(Error::Expired)
    );
    assert_eq!(
        rsa(&[RSA_LEAF, RSA_INT], &[RSA_ROOT], Some(JAN_2026 - 1)),
        Some(Error::NotYetValid)
    );
    assert_eq!(
        verify_chain(&[RSA_LEAF, RSA_INT], &[RSA_ROOT], "example.net", Some(NOW)).err(),
        Some(Error::NameMismatch)
    );
    assert_eq!(
        rsa(&[RSA_LEAF, RSA_INT], &[EC_ROOT], Some(NOW)),
        Some(Error::UnknownIssuer)
    );
    assert_eq!(
        rsa(&[RSA_LEAF], &[RSA_ROOT], Some(NOW)),
        Some(Error::UnknownIssuer)
    );
    assert_eq!(
        rsa(&[RSA_LEAF, RSA_INT], roots::DEFAULT, Some(NOW)),
        Some(Error::UnknownIssuer)
    );
    assert_eq!(rsa(&[], &[RSA_ROOT], None), Some(Error::Malformed));

    // A flipped bit in the leaf signature, then in the intermediate signature.
    let mut bad_leaf = RSA_LEAF.to_vec();
    *bad_leaf.last_mut().unwrap() ^= 1;
    assert_eq!(
        rsa(&[&bad_leaf, RSA_INT], &[RSA_ROOT], Some(NOW)),
        Some(Error::BadSignature)
    );
    let mut bad_int = RSA_INT.to_vec();
    *bad_int.last_mut().unwrap() ^= 1;
    assert_eq!(
        rsa(&[RSA_LEAF, &bad_int], &[RSA_ROOT], Some(NOW)),
        Some(Error::BadSignature)
    );
    let mut bad_ec = EC_LEAF.to_vec();
    let len = bad_ec.len();
    bad_ec[len - 3] ^= 1;
    assert_eq!(
        verify_chain(&[&bad_ec, EC_INT], &[EC_ROOT], "www.example.org", None).err(),
        Some(Error::BadSignature)
    );

    // Issued by a leaf (no CA bit), and by a CA beyond its pathlen:0.
    assert_eq!(
        verify_chain(
            &[NOTCA_LEAF, RSA_LEAF, RSA_INT],
            &[RSA_ROOT],
            "sub.example.com",
            Some(NOW)
        )
        .err(),
        Some(Error::NotCa)
    );
    assert_eq!(
        verify_chain(
            &[PLEN_LEAF, PLEN_INT1, PLEN_INT0],
            &[RSA_ROOT],
            "deep.example.com",
            Some(NOW)
        )
        .err(),
        Some(Error::NotCa)
    );

    // Seven intermediates: one more than the limit; six are fine.
    assert_eq!(
        verify_chain(&LONG, &[EC_ROOT], "long.example.org", Some(NOW)).err(),
        Some(Error::ChainTooLong)
    );
    verify_chain(&LONG, &[LONG[7]], "long.example.org", Some(NOW)).unwrap();

    // The leaf itself is malformed or unsupported.
    assert_eq!(
        verify_chain(&[CRIT_LEAF, EC_INT], &[EC_ROOT], "crit.example.org", None).err(),
        Some(Error::Unsupported)
    );
    assert_eq!(
        rsa(&[&RSA_LEAF[..100]], &[RSA_ROOT], None),
        Some(Error::Malformed)
    );
}

#[test]
fn signature_dispatch() {
    let root = Certificate::parse(RSA_ROOT).unwrap();
    let ec = Certificate::parse(EC_ROOT).unwrap();
    assert!(verify_signature(
        &root.public_key,
        root.signature_algorithm,
        root.tbs,
        root.signature
    ));
    assert!(verify_signature(
        &ec.public_key,
        ec.signature_algorithm,
        ec.tbs,
        ec.signature
    ));
    // Wrong key type for the algorithm, wrong hash, wrong message.
    assert!(!verify_signature(
        &ec.public_key,
        root.signature_algorithm,
        root.tbs,
        root.signature
    ));
    assert!(!verify_signature(
        &root.public_key,
        SignatureAlgorithm::RsaPkcs1Sha384,
        root.tbs,
        root.signature
    ));
    assert!(!verify_signature(
        &root.public_key,
        root.signature_algorithm,
        &root.tbs[1..],
        root.signature
    ));
    assert!(!verify_signature(
        &ec.public_key,
        SignatureAlgorithm::EcdsaSha256,
        ec.tbs,
        ec.signature
    ));
    assert!(!verify_signature(
        &ec.public_key,
        ec.signature_algorithm,
        ec.tbs,
        &ec.signature[1..]
    ));
    let ed = Certificate::parse(ED_ROOT).unwrap();
    assert!(verify_signature(
        &ed.public_key,
        SignatureAlgorithm::Ed25519,
        ed.tbs,
        ed.signature
    ));
    assert!(!verify_signature(
        &ed.public_key,
        SignatureAlgorithm::Ed25519,
        ed.tbs,
        &ed.signature[..63]
    ));
}

#[test]
fn embedded_roots_parse_and_self_verify() {
    assert_eq!(roots::DEFAULT.len(), 17);
    let mut verified = 0;
    for der in roots::DEFAULT {
        let anchor = Parsed::parse(der).unwrap();
        assert!(anchor.is_ca && anchor.issuer == anchor.subject);
        assert!(anchor.not_after > NOW, "expired root");
        match Certificate::parse(der) {
            Ok(c) => {
                assert!(
                    verify_signature(&c.public_key, c.signature_algorithm, c.tbs, c.signature),
                    "{:?}",
                    c.common_name
                );
                verified += 1;
            }
            Err(e) => assert_eq!(e, Error::Unsupported), // SHA-1 self-signatures
        }
    }
    assert!(verified >= 15, "{verified}");
}

#[test]
fn purpose_restrictions() {
    let roots = [cert!("ec-root")];
    let now = Some(NOW);
    let host = "purpose.example.org";
    let ok = verify_chain(&[cert!("purpose-ok"), cert!("ec-int")], &roots, host, now).unwrap();
    assert!(ok.server_auth && ok.digital_signature);
    // extendedKeyUsage = clientAuth only.
    let client = Certificate::parse(cert!("purpose-client")).unwrap();
    assert!(!client.server_auth && client.digital_signature);
    assert_eq!(
        verify_chain(
            &[cert!("purpose-client"), cert!("ec-int")],
            &roots,
            host,
            now
        )
        .err(),
        Some(Error::WrongPurpose)
    );
    // keyUsage without digitalSignature.
    let nosign = Certificate::parse(cert!("purpose-nosign")).unwrap();
    assert!(nosign.server_auth && !nosign.digital_signature);
    assert_eq!(
        verify_chain(
            &[cert!("purpose-nosign"), cert!("ec-int")],
            &roots,
            host,
            now
        )
        .err(),
        Some(Error::WrongPurpose)
    );
    // Without the extensions there is no restriction.
    let plain = Certificate::parse(cert!("ec-leaf")).unwrap();
    assert!(plain.server_auth && plain.digital_signature);
}

/// Verifies `leaf` under intermediate `int` and the constraints root.
fn under(leaf: &'static [u8], int: &'static [u8], host: &str) -> Result<(), Error> {
    verify_chain(&[leaf, int], &[cert!("nc-root")], host, Some(NOW)).map(|_| ())
}

/// Audit 2026-10-25 D, H1: a non-critical nameConstraints extension was
/// ignored, so an intermediate limited to good.example could vouch for any
/// name (the webpki/JSSE pattern). Critical or not, it now applies.
#[test]
fn name_constraints_bind_intermediates() {
    let int = Certificate::parse(cert!("nc-int")).unwrap();
    let nc = int.name_constraints.as_ref().unwrap();
    assert_eq!(
        (nc.permitted.as_slice(), nc.excluded.len()),
        (&["good.example"][..], 0)
    );
    assert_eq!(
        under(cert!("nc-ok"), cert!("nc-int"), "www.good.example"),
        Ok(())
    );
    assert_eq!(
        under(cert!("nc-evil"), cert!("nc-int"), "www.evil.example"),
        Err(Error::NameConstraint)
    );
    // Every name of the leaf is checked, not only the one asked for.
    assert_eq!(
        under(cert!("nc-mixed"), cert!("nc-int"), "www.good.example"),
        Err(Error::NameConstraint)
    );
    assert_eq!(
        under(cert!("nc-wild"), cert!("nc-int"), "a.good.example"),
        Ok(())
    );
    // A constrained chain needs a subjectAltName: no common name fallback.
    assert_eq!(
        under(cert!("nc-cn"), cert!("nc-int"), "www.good.example"),
        Err(Error::NameConstraint)
    );
    // Critical: understood now, so no longer refused as unsupported.
    assert_eq!(
        under(
            cert!("nc-crit-ok"),
            cert!("nc-crit-int"),
            "www.good.example"
        ),
        Ok(())
    );
    assert_eq!(
        under(
            cert!("nc-crit-evil"),
            cert!("nc-crit-int"),
            "www.evil.example"
        ),
        Err(Error::NameConstraint)
    );
    // Excluded subtrees, and a wildcard that could stand for one.
    assert_eq!(
        under(
            cert!("nc-excl-ok"),
            cert!("nc-excl-int"),
            "www.good.example"
        ),
        Ok(())
    );
    assert_eq!(
        under(
            cert!("nc-excl-bad"),
            cert!("nc-excl-int"),
            "x.bad.good.example"
        ),
        Err(Error::NameConstraint)
    );
    assert_eq!(
        under(
            cert!("nc-excl-wild"),
            cert!("nc-excl-int"),
            "www.good.example"
        ),
        Err(Error::NameConstraint)
    );
}

/// Audit 2026-10-25 D, H2: an intermediate whose extendedKeyUsage allows
/// only e-mail protection could issue TLS server certificates we accepted.
#[test]
fn intermediates_need_server_auth() {
    let host = "www.eku.example";
    assert_eq!(
        under(cert!("eku-tls-leaf"), cert!("eku-tls-int"), host),
        Ok(())
    );
    assert_eq!(
        under(cert!("eku-mail-leaf"), cert!("eku-mail-int"), host),
        Err(Error::WrongPurpose)
    );
}

#[test]
fn name_constraint_subtrees() {
    let nc =
        |permitted: &'static [&'static str], excluded: &'static [&'static str]| NameConstraints {
            permitted: permitted.to_vec(),
            excluded: excluded.to_vec(),
            ip_subtrees: false,
        };
    let good = nc(&["good.example"], &[]);
    for name in [
        "good.example",
        "a.good.example",
        "A.B.Good.Example",
        "*.good.example",
        "good.example.",
    ] {
        assert!(good.allows(name), "{name}");
    }
    for name in [
        "notgood.example",
        "good.example.evil",
        "example",
        "*.example",
        "evil.example",
    ] {
        assert!(!good.allows(name), "{name}");
    }
    // A leading dot: the subdomains only.
    let subs = nc(&[".good.example"], &[]);
    assert!(subs.allows("a.good.example") && subs.allows("*.good.example"));
    assert!(!subs.allows("good.example"));
    // The empty constraint holds every name.
    assert!(nc(&[""], &[]).allows("anything.example"));
    let excl = nc(&[], &["bad.example"]);
    assert!(excl.allows("good.example") && excl.allows("notbad.example"));
    for name in ["bad.example", "x.bad.example", "*.bad.example", "*.example"] {
        assert!(!excl.allows(name), "{name}");
    }
}

/// A DER element: `tag`, its definite length and `value`.
fn tlv(tag: u8, value: &[u8]) -> Vec<u8> {
    let mut out = vec![tag];
    match value.len() {
        n if n < 0x80 => out.push(n as u8),
        n if n < 0x100 => out.extend([0x81, n as u8]),
        n => out.extend([0x82, (n >> 8) as u8, n as u8]),
    }
    out.extend_from_slice(value);
    out
}

/// An unsigned certificate (the parser does not check signatures) with an
/// Ed25519 or the given key and these extensions.
fn built(spki: Option<Vec<u8>>, extensions: &[Vec<u8>]) -> Vec<u8> {
    let ed25519 = tlv(0x30, &tlv(0x06, &[0x2b, 0x65, 0x70]));
    let name = tlv(
        0x30,
        &tlv(
            0x31,
            &tlv(0x30, &[tlv(0x06, &[0x55, 4, 3]), tlv(0x0c, b"x")].concat()),
        ),
    );
    let validity = tlv(
        0x30,
        &[tlv(0x17, b"250101000000Z"), tlv(0x17, b"350101000000Z")].concat(),
    );
    let spki = spki.unwrap_or_else(|| {
        tlv(
            0x30,
            &[
                ed25519.clone(),
                tlv(0x03, &[[0u8].as_slice(), &[7u8; 32]].concat()),
            ]
            .concat(),
        )
    });
    let tbs = tlv(
        0x30,
        &[
            tlv(0xa0, &tlv(0x02, &[2])),
            tlv(0x02, &[1]),
            ed25519.clone(),
            name.clone(),
            validity,
            name,
            spki,
            tlv(0xa3, &tlv(0x30, &extensions.concat())),
        ]
        .concat(),
    );
    tlv(0x30, &[tbs, ed25519, tlv(0x03, &[0u8; 65])].concat())
}

fn extension(oid: &[u8], value: &[u8]) -> Vec<u8> {
    tlv(0x30, &[tlv(0x06, oid), tlv(0x04, value)].concat())
}

fn san(names: &[&[u8]]) -> Vec<u8> {
    let names: Vec<u8> = names.iter().flat_map(|n| tlv(0x82, n)).collect();
    extension(&[0x55, 0x1d, 0x11], &tlv(0x30, &names))
}

/// Audit 2026-10-25 D, L1, L2, L4 and B, L4.
#[test]
fn hardened_parsing() {
    // The builder itself makes a certificate the parser takes.
    let ok = built(None, &[san(&[b"www.good.example"])]);
    assert_eq!(
        Certificate::parse(&ok).unwrap().dns_names,
        ["www.good.example"]
    );
    // Two basicConstraints (CA:FALSE, then CA:TRUE): parsers keeping the
    // first and the last would disagree on whether it is a CA.
    let bc = |ca: bool| {
        let body = if ca { tlv(0x01, &[0xff]) } else { Vec::new() };
        extension(&[0x55, 0x1d, 0x13], &tlv(0x30, &body))
    };
    assert_eq!(
        Certificate::parse(&built(None, &[bc(false), bc(true)])).err(),
        Some(Error::Malformed)
    );
    assert_eq!(
        Certificate::parse(&built(None, &[san(&[b"a.example"]), san(&[b"b.example"])])).err(),
        Some(Error::Malformed)
    );
    // NUL, escape, space and empty names.
    for name in [&b"www.bank.com\0.evil.com"[..], b"\x1b[31mred", b"a b", b""] {
        assert_eq!(
            Certificate::parse(&built(None, &[san(&[name])])).err(),
            Some(Error::Malformed)
        );
    }
    // RSA keys: a 2048-bit modulus with 65537 parses; a tiny or huge
    // exponent, an even one, or a modulus outside 1024..8192 bits do not.
    let rsa = |n_len: usize, e: &[u8]| {
        let alg = tlv(
            0x30,
            &[
                tlv(
                    0x06,
                    &[0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x01],
                ),
                tlv(0x05, &[]),
            ]
            .concat(),
        );
        let mut n = vec![0x00, 0xc0];
        n.resize(n_len + 1, 0x01);
        let key = tlv(0x30, &[tlv(0x02, &n), tlv(0x02, e)].concat());
        let bits = tlv(0x03, &[[0u8].as_slice(), &key].concat());
        Certificate::parse(&built(Some(tlv(0x30, &[alg, bits].concat())), &[])).map(|_| ())
    };
    assert_eq!(rsa(256, &[0x01, 0x00, 0x01]), Ok(()));
    assert_eq!(rsa(256, &[0x03]), Ok(()));
    for (n_len, e) in [
        (256, &[0x01][..]),
        (256, &[0x01, 0x00, 0x00]),
        (256, &[0x7f, 0xff, 0xff, 0xff, 0xff]),
        (64, &[0x01, 0x00, 0x01]),
        (1025, &[0x01, 0x00, 0x01]),
    ] {
        assert_eq!(rsa(n_len, e), Err(Error::Unsupported), "{n_len} {e:?}");
    }
    // A trusted CA certificate presented as the server's.
    assert_eq!(
        verify_chain(
            &[cert!("ca-as-leaf")],
            &[cert!("nc-root")],
            "www.good.example",
            Some(NOW)
        )
        .err(),
        Some(Error::WrongPurpose)
    );
}

/// Audit of incident 0029, L1, L2, L3 and L4: restrictions on roots, two
/// constrained CAs in one path, IP hosts, and the bounds on work done
/// before a chain is trusted.
#[test]
fn constraints_on_roots_paths_and_ip_hosts() {
    let at = Some(NOW);
    let ncr = [cert!("ncr-root")];
    assert!(verify_chain(&[cert!("ncr-ok")], &ncr, "www.good.example", at).is_ok());
    assert_eq!(
        verify_chain(&[cert!("ncr-evil")], &ncr, "www.evil.example", at).err(),
        Some(Error::NameConstraint)
    );
    assert_eq!(
        verify_chain(
            &[cert!("ekur-leaf")],
            &[cert!("ekur-root")],
            "www.eku.example",
            at
        )
        .err(),
        Some(Error::WrongPurpose)
    );
    // nc-int permits good.example, nc2-int below it only sub.good.example.
    let roots = [cert!("nc-root")];
    let path = |leaf| [leaf, cert!("nc2-int"), cert!("nc-int")];
    assert!(verify_chain(&path(cert!("nc2-ok")), &roots, "www.sub.good.example", at).is_ok());
    assert_eq!(
        verify_chain(&path(cert!("nc2-out")), &roots, "www.good.example", at).err(),
        Some(Error::NameConstraint)
    );
    // A CA with iPAddress subtrees, which are not evaluated: an IP host is
    // refused, a DNS host is not.
    let ip = [cert!("ip-leaf"), cert!("ip-int")];
    assert_eq!(
        verify_chain(&ip, &roots, "10.0.2.2", at).err(),
        Some(Error::NameConstraint)
    );
    assert!(verify_chain(&ip, &roots, "www.ip.example", at).is_ok());
    // A CA certificate that is itself a trust anchor, presented as the
    // server's.
    let ca = [cert!("ca-as-leaf")];
    assert_eq!(
        verify_chain(&ca, &ca, "www.good.example", at).err(),
        Some(Error::WrongPurpose)
    );
    // An IP host matches a dNSName spelling it, never a wildcard.
    let wild = built(None, &[san(&[b"*.0.2.2"])]);
    assert!(!matches_hostname(
        &Certificate::parse(&wild).unwrap(),
        "10.0.2.2"
    ));
    let exact = built(None, &[san(&[b"10.0.2.2"])]);
    assert!(matches_hostname(
        &Certificate::parse(&exact).unwrap(),
        "10.0.2.2"
    ));
    assert!(
        !is_ipv4("10.0.2") && !is_ipv4("10.0.2.256") && !is_ipv4("a.0.2.2") && is_ipv4("10.0.2.2")
    );
    // At most MAX_EXTENSIONS extensions.
    let many: Vec<Vec<u8>> = (0..=32u8)
        .map(|i| extension(&[0x2a, 0x03, i], &[0x05, 0x00]))
        .collect();
    assert_eq!(
        Certificate::parse(&built(None, &many)).err(),
        Some(Error::Unsupported)
    );
    // Leaf names × subtrees within NAME_CONSTRAINT_BUDGET.
    let names: Vec<Vec<u8>> = (0..200)
        .map(|i| alloc::format!("n{i}.good.example").into_bytes())
        .collect();
    let refs: Vec<&[u8]> = names.iter().map(|n| n.as_slice()).collect();
    let der = built(None, &[san(&refs)]);
    let leaf = Certificate::parse(&der).unwrap();
    let wide = NameConstraints {
        permitted: vec!["good.example"; 100],
        excluded: Vec::new(),
        ip_subtrees: false,
    };
    assert_eq!(
        check_name_constraints(&leaf, "n1.good.example", Some(&wide)),
        Err(Error::NameConstraint)
    );
    let narrow = NameConstraints {
        permitted: vec!["good.example"; 10],
        ..wide
    };
    assert_eq!(
        check_name_constraints(&leaf, "n1.good.example", Some(&narrow)),
        Ok(())
    );
}

/// Audit 2026-10-25 D, M1: no clock, or one that reads before the build,
/// skipped or defeated the validity check.
#[test]
fn certificates_are_checked_at_no_earlier_than_the_floor() {
    assert_eq!(check_time(None), ValidityTime::AtLeast(TIME_FLOOR));
    assert_eq!(
        check_time(Some(946_684_800)),
        ValidityTime::AtLeast(TIME_FLOOR)
    );
    assert_eq!(
        check_time(Some(TIME_FLOOR + 5)),
        ValidityTime::Clock(TIME_FLOOR + 5)
    );
    // Without a trusted clock only expiry before the floor is refused: a
    // leaf issued after the floor passes, one expired before it fails
    // (audit of incident 0036, H1: notBefore was checked against the floor
    // too, refusing every certificate renewed after the release).
    let roots = [cert!("rsa-root")];
    let chain = [cert!("rsa-leaf"), cert!("rsa-int")];
    let leaf = Certificate::parse(cert!("rsa-leaf")).unwrap();
    let at = |floor| {
        verify_chain(
            &chain,
            &roots,
            "www.example.com",
            ValidityTime::AtLeast(floor),
        )
    };
    assert!(
        at(leaf.not_before - 1).is_ok(),
        "issued after the floor: fine"
    );
    assert!(at(leaf.not_after).is_ok());
    assert_eq!(at(leaf.not_after + 1).err(), Some(Error::Expired));
}

#[test]
fn distrusted_keys_are_refused_anywhere_in_the_chain() {
    let spki = |der| aricode_crypto::sha256::sha256(Certificate::parse(der).unwrap().spki);
    let chain = [RSA_LEAF, RSA_INT];
    let host = "www.example.com";
    verify_chain_with(&chain, &[RSA_ROOT], &[], host, Some(NOW)).unwrap();
    // An unrelated key changes nothing.
    verify_chain_with(&chain, &[RSA_ROOT], &[spki(EC_INT)], host, Some(NOW)).unwrap();
    for distrusted in [RSA_LEAF, RSA_INT, RSA_ROOT] {
        assert_eq!(
            verify_chain_with(&chain, &[RSA_ROOT], &[spki(distrusted)], host, Some(NOW)).err(),
            Some(Error::Distrusted)
        );
    }
    // The default list is what verify_chain applies.
    assert_eq!(
        verify_chain(&chain, &[RSA_ROOT], host, Some(NOW)).is_ok(),
        roots::DISTRUSTED.is_empty()
    );
}
